import{_ as t,o as s,c as n,a3 as o}from"./chunks/framework.qCVWde4n.js";const g=JSON.parse('{"title":"审核后台（站长）","description":"","frontmatter":{},"headers":[],"relativePath":"repo/admin.md","filePath":"repo/admin.md","lastUpdated":null}'),e={name:"repo/admin.md"};function r(d,a,l,i,p,c){return s(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="审核后台-站长" tabindex="-1">审核后台（站长） <a class="header-anchor" href="#审核后台-站长" aria-label="Permalink to &quot;审核后台（站长）&quot;">​</a></h1><p>仓库有一套<strong>网站后台</strong>：玩家上传的 Mod 全部进「待审核」，你在后台点「通过」才会上架，点「驳回」则退回。这一页讲怎么用它。</p><div class="warning custom-block"><p class="custom-block-title">本页含运维操作，请勿公开张贴</p><p>里面出现的地址、命令请勿转发到公开群聊，避免被人拿去尝试未授权操作。</p></div><h2 id="后台在哪" tabindex="-1">后台在哪 <a class="header-anchor" href="#后台在哪" aria-label="Permalink to &quot;后台在哪&quot;">​</a></h2><p>打开仓库页，右上角点「<strong>管理后台</strong>」，或直接访问 <code>/admin/</code>。</p><p>进入前要输一次<strong>管理员密钥</strong>。输对了会记住，下次打开直接进；换浏览器 / 清了缓存要重输。</p><h2 id="后台怎么看数据" tabindex="-1">后台怎么看数据 <a class="header-anchor" href="#后台怎么看数据" aria-label="Permalink to &quot;后台怎么看数据&quot;">​</a></h2><p>顶部四个指标：</p><table tabindex="0"><thead><tr><th>指标</th><th>含义</th></tr></thead><tbody><tr><td><strong>待审核</strong></td><td>等你处理的提交，最该关心的数字</td></tr><tr><td><strong>仓库在架</strong></td><td>仓库里当前真实可下载的 Mod 数</td></tr><tr><td><strong>仓库总量</strong></td><td>仓库列表里的总条数（含历史手工放入的）</td></tr><tr><td><strong>已驳回</strong></td><td>累计被退回的提交数</td></tr></tbody></table><p>下面一排分类页：<strong>待审核 / 已上架 / 已驳回 / 全部 / 操作日志</strong>。</p><h2 id="审一个-mod" tabindex="-1">审一个 Mod <a class="header-anchor" href="#审一个-mod" aria-label="Permalink to &quot;审一个 Mod&quot;">​</a></h2><ol><li><p>在「<strong>待审核</strong>」页找到那条记录；</p></li><li><p>点「<strong>详情</strong>」看完整 <code>mod.json</code>、上传者、来源 IP；</p></li><li><p>决定：</p><ul><li><strong>通过并上架</strong> —— 立刻写进仓库，自动生成分享码，所有人可下载；</li><li><strong>驳回</strong> —— 退回，可附一句原因（作者能看到）。</li></ul></li></ol><p>已上架的记录还能「<strong>下架</strong>」（从仓库撤掉但不删记录）和「<strong>删除</strong>」（彻底移除，不可恢复，<strong>两段确认</strong>防误点）。</p><h2 id="「已移除」标签是什么意思" tabindex="-1">「已移除」标签是什么意思 <a class="header-anchor" href="#「已移除」标签是什么意思" aria-label="Permalink to &quot;「已移除」标签是什么意思&quot;">​</a></h2><p>如果某条已上架的记录，在仓库包里<strong>找不到对应的文件</strong>（比如你手工把包删了），后台会给它打上「<strong>已移除</strong>」标签，并提供「重新上架」按钮。这样管理员一眼就能看出「数据库里说有，仓库里其实没有」的不一致状态。</p><h2 id="操作日志" tabindex="-1">操作日志 <a class="header-anchor" href="#操作日志" aria-label="Permalink to &quot;操作日志&quot;">​</a></h2><p>「<strong>操作日志</strong>」页记录每一次<strong>通过 / 驳回 / 下架 / 删除</strong>，包含时间与操作对象。要回溯「这个 Mod 什么时候被谁下架的」，看这里。</p><h2 id="重建索引" tabindex="-1">重建索引 <a class="header-anchor" href="#重建索引" aria-label="Permalink to &quot;重建索引&quot;">​</a></h2><p>「<strong>重建索引</strong>」按钮会<strong>以 <code>packages/</code> 目录为准</strong>重新汇总仓库列表：</p><ul><li>手工拷进去的 Mod 会被正确收进来（不会被索引吃掉）；</li><li>已删除的包会从列表里消失；</li><li>数据库里没有元信息的老包，会从 <code>mod.json</code> 现推作者 / 版本 / 参数。</li></ul><p>平时<strong>不需要手动点</strong>——上传通过 / 下架 / 删除时会自动重建。只有你手工动过 <code>packages/</code> 目录时才需要。</p><h2 id="自建一套同样的系统" tabindex="-1">自建一套同样的系统 <a class="header-anchor" href="#自建一套同样的系统" aria-label="Permalink to &quot;自建一套同样的系统&quot;">​</a></h2><p>这套后台由两部分组成：</p><table tabindex="0"><thead><tr><th>部分</th><th>作用</th></tr></thead><tbody><tr><td><strong>网站前端</strong></td><td><code>mods/</code>（仓库页 + 上传区）、<code>admin/</code>（审核后台）——纯静态，放 nginx 目录即可</td></tr><tr><td><strong>后端服务</strong></td><td>一个<strong>零依赖</strong>的 Python 脚本（只用标准库），负责收上传、存数据、生成分享码</td></tr></tbody></table><p>后端跑起来只需要 Python，<strong>不需要装任何第三方库、不需要数据库</strong>（数据用 SQLite 单文件存）。</p><h3 id="目录约定" tabindex="-1">目录约定 <a class="header-anchor" href="#目录约定" aria-label="Permalink to &quot;目录约定&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/                      ← 网站根下的仓库目录</span></span>
<span class="line"><span>  index.html               ← 仓库页（含上传区）</span></span>
<span class="line"><span>  index.json               ← 仓库清单（网页与游戏端共用这一份数据）</span></span>
<span class="line"><span>  af-naval.css / .js       ← 共享设计系统</span></span>
<span class="line"><span>  packages/                ← 每个 Mod 的 .json 包 + .txt 分享码</span></span>
<span class="line"><span>  uploads/                 ← 上传的原包体（存底）</span></span>
<span class="line"><span>admin/</span></span>
<span class="line"><span>  index.html               ← 审核后台</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>后端会自动：</p><ol><li>校验上传的 <code>mod.json</code>（格式、必填、重名、内容重复、大小）；</li><li>用<strong>内容哈希</strong>给每个 Mod 生成不冲突的 ASCII 别名（中文名才不会互相覆盖）；</li><li>过审时写包 + 生成 <code>AFMOD1:</code> 分享码 + 重建 <code>index.json</code>；</li><li>记录来源 IP 与完整操作留痕。</li></ol><h3 id="关键设计-踩过的坑" tabindex="-1">关键设计（踩过的坑） <a class="header-anchor" href="#关键设计-踩过的坑" aria-label="Permalink to &quot;关键设计（踩过的坑）&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">两个真踩过的坑，自建时务必注意</p><p><strong>1. 重名覆盖</strong>：早期用中文名生成 ASCII 别名时会退化成同一个 <code>mod</code>，导致后发布的把先发布的<strong>覆盖</strong>掉，三个人下载到的是同一个包。现在改为：无 ASCII 可用时用 <code>md5(名字)[:8]</code> 生成 <code>mod-&lt;8位&gt;</code> 保证唯一。</p><p><strong>2. 「已上架」数字虚高</strong>：如果后台只数数据库里的 approved 记录，一旦有人手工删了 <code>packages/</code> 里的包，后台还会说「已上架 N」，和仓库对不上。现在<strong>以 <code>packages/</code> 目录为权威来源</strong>统计，两边永远一致。</p></div><h2 id="备份建议" tabindex="-1">备份建议 <a class="header-anchor" href="#备份建议" aria-label="Permalink to &quot;备份建议&quot;">​</a></h2><p>真正要备份的是两样：</p><table tabindex="0"><thead><tr><th>要备份</th><th>说明</th></tr></thead><tbody><tr><td><strong>上传的源包</strong></td><td><code>packages/</code> 里的 <code>.json</code>（含每个 Mod 的完整内容）</td></tr><tr><td><strong>数据库</strong></td><td>审核记录、留痕、来源 IP</td></tr></tbody></table><p><code>index.json</code> 随时能从 <code>packages/</code> 重建，<strong>不用单独备份</strong>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>作者侧流程 → <a href="/AtlanticFleetSite/docs/repo/publish">上传你的 Mod</a></li><li>仓库页都有什么 → <a href="/AtlanticFleetSite/docs/repo/browse">浏览仓库</a></li></ul>`,37)])])}const b=t(e,[["render",r]]);export{g as __pageData,b as default};
